public void Solve(char[][] board)
{
    int m = board.Length, n = board[0].Length;
    var queue = new Queue<(int, int)>();
    for (int i = 0; i < m; i++)
    {
        if (board[i][0] == 'O') { board[i][0] = 'T'; queue.Enqueue((i, 0)); }
        if (board[i][n - 1] == 'O') { board[i][n - 1] = 'T'; queue.Enqueue((i, n - 1)); }
    }
    for (int j = 0; j < n; j++)
    {
        if (board[0][j] == 'O') { board[0][j] = 'T'; queue.Enqueue((0, j)); }
        if (board[m - 1][j] == 'O') { board[m - 1][j] = 'T'; queue.Enqueue((m - 1, j)); }
    }
    int[][] dirs = { new[] { 0, 1 }, new[] { 1, 0 }, new[] { 0, -1 }, new[] { -1, 0 } };
    while (queue.Count > 0)
    {
        var (i, j) = queue.Dequeue();
        foreach (var d in dirs)
        {
            int ni = i + d[0], nj = j + d[1];
            if (ni >= 0 && nj >= 0 && ni < m && nj < n && board[ni][nj] == 'O')
            {
                board[ni][nj] = 'T';
                queue.Enqueue((ni, nj));
            }
        }
    }
    for (int i = 0; i < m; i++)
        for (int j = 0; j < n; j++)
            board[i][j] = board[i][j] == 'T' ? 'O' : 'X';
}
